'use strict';
nav.splice(7,0,['exchange','08','Siddisbørsen']);nav.forEach((n,i)=>n[1]=String(i+1).padStart(2,'0'));
const priorExchangeRender=render;
let selectedStock='NFE',stockSide='buy',stockPeriod=52;
const stockMoney=n=>n.toLocaleString('nb-NO',{minimumFractionDigits:2,maximumFractionDigits:2})+' kr';
function stockChart(id,mini=false){const h=s.exchange.history.slice(-(stockPeriod+1)),values=h.map(p=>p[id]/100),w=mini?140:700,height=mini?40:180,min=Math.min(...values)*.99,max=Math.max(...values)*1.01,points=values.map((v,i)=>`${values.length<2?0:i/(values.length-1)*w},${height-8-(v-min)/(max-min||1)*(height-16)}`);if(points.length===1)points.push(`${w},${height/2}`);const company=G.STOCKS.find(c=>c.id===id);return `<svg class="${mini?'stock-spark':'stock-chart'}" viewBox="0 0 ${w} ${height}" role="img" aria-label="Kursutvikling for ${company.name}, ${h.length} ukesobservasjoner"><path d="M0 ${height*.25}H${w}M0 ${height*.5}H${w}M0 ${height*.75}H${w}" stroke="#40504d" stroke-width="1" fill="none"/><polyline points="${points.join(' ')}" fill="none" stroke="${company.color}" stroke-width="${mini?2:3}" vector-effect="non-scaling-stroke"/></svg>`;}
function exchangePage(){const e=s.exchange,c=G.STOCKS.find(c=>c.id===selectedStock),p=e.positions[c.id]||{qty:0,cost:0},value=G.stockValue(s),basis=Object.values(e.positions).reduce((n,p)=>n+p.cost,0),history=e.history.slice(-(stockPeriod+1)),first=history[0][c.id],change=(e.prices[c.id]/first-1)*100,used=e.usedWeek===s.week?(e.used[c.id]||0):0,open=s.rankLevel>=3,leverage=G.marketLeverage(s);
return `<div class="page-title"><div><span class="section-kicker">SIDDISBØRSEN / NORA VED EIERBORDET</span><h1>EIER DU EN DEL,<br>FÅR DU ET ORD.</h1><p>«Aksjer e òg folk du må stå i rom med», sier Nora. Langsiktig eierskap kan åpne dører når Bjørnar presser eller Haugland ber om svar. Kursene oppdateres ved ukesoppgjør; en manuell handel bruker én dag.</p></div><span class="rubber-stamp">${open?'BØRSEN ER ÅPEN':'ÅPNER SOM BAKMANN'}</span></div>
<section class="exchange-ticker"><span>SIDDISBØRS-INDEKS <b>${G.stockIndex(s).toLocaleString('nb-NO')}</b></span><span>PORTEFØLJE <b>${kr(value)}</b></span><span>UREALISERT <b class="${value-basis>=0?'profit':'loss'}">${kr(value-basis)}</b></span><span>UTBYTTE MOTTATT <b>${kr(e.dividends)}</b></span></section>
<section class="active-project"><h2>Gi Nora en stående eierfullmakt.</h2><p>Hver fjerde uke kan Nora investere 10 % av kontantene utover driftsreserven og kapitalen som trengs til neste nødvendige ekspansjonstrinn før Gudfar. Planen handler uten ekstra kalenderdager, og kjøper innenfor de samme prisene og likviditetsgrensene. Bank og gjeldsdekning holdes utenfor. Du kan fortsatt kjøpe og selge manuelt. ${G.expansionReserve(s)>0?'Holdes nå av til nettverket: '+kr(G.expansionReserve(s))+'.':''}</p><div class="market-actions">${[['manual','Velg selv'],['income','Utbyttekurv'],['diverse','Alle åtte sektorer'],...G.MARKET_MANDATES.map(m=>[m.id,m.name])].map(([id,name])=>btn('stockPlan',id,name+(e.plan===id?' ✓':''),!open,'button ghost')).join('')}</div></section>
<section class="council-card"><span class="section-kicker">NORA / ${esc(leverage.name)}</span><h2>${leverage.ready?'Et sete du har betalt for.':'Tillit tar tretten uker.'}</h2><p>${esc(leverage.reason)}</p><p>Langsiktig beholdning ${kr(leverage.seasonedValue)} / ${kr(leverage.required)}. Kapitalen kan falle i verdi og kan ikke samtidig brukes til drift eller nye områder.</p>${meter(leverage.required?leverage.seasonedValue/leverage.required*100:0)}<p>Forhandlingsfordel: ${(leverage.rival*100).toLocaleString('nb-NO',{maximumFractionDigits:1})} prosentpoeng mot Bjørnar · ${(leverage.case*100).toLocaleString('nb-NO',{maximumFractionDigits:1})} mot Haugland. Ingen fordel i konfrontasjon. Aksjer inngår i formuen, og gir ingen ekstra produktiv sluttscore.</p><div class="portfolio-grid">${G.MARKET_MANDATES.map(m=>`<article><h3>${esc(m.name)}</h3><p>${esc(m.text)}</p><small>${m.ids.join(' + ')} · minst 13 hele ukeoppgjør</small></article>`).join('')}</div></section>
<div class="exchange-layout"><section class="stock-list"><span class="section-kicker">KURSLISTEN / VELG ET SELSKAP</span>${G.STOCKS.map(x=>{const last=e.history.length>1?e.history[e.history.length-2][x.id]:e.prices[x.id],delta=(e.prices[x.id]/last-1)*100;return `<button class="stock-row ${x.id===c.id?'chosen':''}" data-stock="${x.id}"><span><b>${x.id}</b><small>${x.sector}</small></span><span>${x.name}</span><span class="stock-row-price"><strong>${stockMoney(e.prices[x.id]/100)}</strong><small class="${delta>=0?'profit':'loss'}">${delta>=0?'+':''}${delta.toFixed(2).replace('.',',')} % / uke</small></span>${stockChart(x.id,true)}</button>`;}).join('')}</section>
<section class="stock-detail"><span class="section-kicker">${c.sector.toUpperCase()} / ${c.id}</span><div class="between"><h2>${c.name}</h2><strong>${stockMoney(e.prices[c.id]/100)}</strong></div><div class="market-actions">${[13,26,52].map(n=>`<button class="button ${stockPeriod===n?'brass':'ghost'}" data-stock-period="${n}">${n} uker</button>`).join('')}<span class="stock-change ${change>=0?'profit':'loss'}">${change>=0?'+':''}${change.toFixed(1).replace('.',',')} % i vist periode</span></div>${stockChart(c.id)}<div class="stock-facts"><span>Utbytteprofil <b>${(c.yield*100).toFixed(1).replace('.',',')} % / år</b></span><span>Kursrisiko <b>${c.vol>=.075?'Svært høy':c.vol>.035?'Høy':'Moderat'}</b></span><span>Din beholdning <b>${p.qty.toLocaleString('nb-NO')} aksjer</b></span><span>Ledig ukelikviditet <b>${(250000-used).toLocaleString('nb-NO')}</b></span><span>Neste utbytteoppgjør <b>${13-s.week%13} uker</b></span></div><p class="small">Utbytte utbetales hver 13. uke til aksjer eid ved forrige ukesregistrering. Det trekkes fra kursen. Utbytteprofilen er en spillsats, ikke en garantert avkastning.</p>
<div class="market-actions"><button class="button ${stockSide==='buy'?'brass':'ghost'}" data-stock-side="buy">Kjøp</button><button class="button ${stockSide==='sell'?'brass':'ghost'}" data-stock-side="sell">Selg</button></div><form id="stockForm"><label>Antall aksjer<input id="stockQty" type="number" min="1" max="${stockSide==='sell'?Math.min(p.qty,250000-used):250000-used}" step="1" value="${stockSide==='sell'?Math.min(p.qty,100):100}" required></label><button class="text-button" id="stockBudget" type="button">${stockSide==='sell'?'Velg hele beholdningen innenfor ukas likviditet':'Beregn mengde for 10 % av fri kapital'}</button><div id="stockOrderQuote" class="planner-quote"></div><button class="button brass" id="stockSubmit" type="submit" ${!open||s.ended||s.event||s.trip?'disabled':''}>${stockSide==='buy'?'Kjøp':'Selg'} ${c.id} · én dag →</button></form><p class="small">0,4 % spread per side, markedspåvirkning ved store ordrer og 0,15 % kurtasje, minst 250 kr. Samlet kjøp og salg er begrenset til 250 000 aksjer per selskap og uke. Ingen shorting eller belåning av porteføljen.</p></section></div>
<h2 class="section-heading">Porteføljen din</h2><div class="portfolio-grid">${G.STOCKS.filter(x=>e.positions[x.id]?.qty).map(x=>{const p=e.positions[x.id],v=p.qty*e.prices[x.id]/100;return `<article class="council-card"><span class="section-kicker">${x.id} / ${x.sector}</span><h2>${x.name}</h2><p>${p.qty.toLocaleString('nb-NO')} aksjer · ${kr(v)} i kursverdi.</p><p>Kostpris inkl. kjøpskurtasje ${kr(p.cost)}. Urealisert <b class="${v>=p.cost?'profit':'loss'}">${kr(v-p.cost)}</b>.</p>${meter(value?v/value*100:0)}<p class="small">${value?(v/value*100).toFixed(1).replace('.',','):0} % av porteføljen.</p><button class="button ghost" data-stock="${x.id}">Åpne aksjen →</button></article>`;}).join('')||'<div class="empty-state"><h2>Ingen aksjer ennå.</h2><p>Velg et selskap og se hele ordren før du handler.</p></div>'}</div><p class="rule-note">Realisert gevinst/tap ${kr(e.realized)} · kurtasje betalt ${kr(e.fees)}. Kursverdi inngår i netto formue, mens imperiets produktive sluttscore holdes separat. Kjøp er en eiendel; det er ikke salgsinntekt.</p>
<h2 class="section-heading">Børsmeldinger</h2><div class="exchange-news">${e.news.slice(0,6).map(n=>`<article><span class="section-kicker">UKE ${n.week} / MARKEDSHENDELSE</span><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p></article>`).join('')||'<article><h3>Nora åpner Siddisbørsen.</h3><p>De første sektorhendelsene kommer mens kampanjen går. Kurser kan både stige og falle.</p></article>'}</div>
${e.trades.length?`<h2 class="section-heading">Siste handler</h2><div class="stock-trades">${e.trades.slice(0,10).map(t=>`<p><b>${t.side==='buy'?'Kjøpt':'Solgt'} ${esc(t.id)}</b> · ${t.qty.toLocaleString('nb-NO')} aksjer · ${kr(t.total)} ${t.side==='buy'?'fra':'til'} kassa${t.profit!==null?' · realisert '+kr(t.profit):''}</p>`).join('')}</div>`:''}`;
}
function bindStockForm(){const input=$('#stockQty'),submit=$('#stockSubmit');function draw(){const q=G.stockQuote(s,selectedStock,stockSide,Number(input.value));submit.disabled=!q?.valid||s.rankLevel<3||s.ended||!!s.event||!!s.trip||(stockSide==='buy'?s.cash<(q?.total||0):s.cash+(q?.total||0)<0);$('#stockOrderQuote').innerHTML=q?`<div class="between"><span>Handelskurs inkl. spread og påvirkning</span><b>${stockMoney(q.unit)}</b></div><div class="between"><span>Kurtasje</span><b>${kr(q.fee)}</b></div><div class="between estimate"><span>${stockSide==='buy'?'Trekkes fra kassa':'Etter kurtasje til kassa'}</span><b>${kr(q.total)}</b></div>${stockSide==='sell'?`<p>Historisk kostpris ${kr(q.basis)} · realisert gevinst/tap ${kr(q.profit)}.</p>`:''}<p class="small">${q.valid?'Ordren bruker én faktisk spilldag.':`Ukas tilgjengelige mengde for ordren er ${q.limit}.`}</p>`:'Velg et positivt, helt antall.';}
input.oninput=draw;$('#stockBudget').onclick=()=>{if(stockSide==='sell')input.value=Math.min(s.exchange.positions[selectedStock]?.qty||0,250000-(s.exchange.used[selectedStock]||0));else input.value=Math.min(250000-(s.exchange.used[selectedStock]||0),Math.max(1,Math.floor((Math.max(0,s.cash-G.capitalReserve(s))*.1-250)/(s.exchange.prices[selectedStock]/100*1.02))));draw();};$('#stockForm').onsubmit=e=>{e.preventDefault();act(stockSide==='buy'?'stockBuy':'stockSell',{id:selectedStock,qty:Number(input.value)});};draw();}
render=function(){const current=view;if(current==='exchange')view='legacy';priorExchangeRender();view=current;if(current==='exchange'){$('#screen').innerHTML=exchangePage();$('#nav [aria-current]')?.removeAttribute('aria-current');$('#nav .active')?.classList.remove('active');const n=$('#nav [data-view="exchange"]');n.classList.add('active');n.setAttribute('aria-current','page');bindStockForm();}};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.stock){selectedStock=b.dataset.stock;render();$('.stock-detail').scrollIntoView({block:'start'});}if(b.dataset.stockSide){stockSide=b.dataset.stockSide;render();$('#stockForm').scrollIntoView({block:'center'});}if(b.dataset.stockPeriod){stockPeriod=+b.dataset.stockPeriod;render();$('.stock-detail').scrollIntoView({block:'start'});}});
render();
